#!/usr/bin/env python3
"""The check for codegen/seed. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("the generated records match the schema", *ws.run([sys.executable, "tools/gen_records.py", "--check"]))
    ws.check("the schema declares the field", re.search('^\\s+po_number:\\s*str\\?', ws.read("schema/records.def"), re.M) is not None)
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom tally._generated.records import Invoice\nfrom tally import export\nfrom tally.invoice import add_line\ninv = Invoice("INV-1", "C-1", "EUR", d.date(2024, 3, 1), po_number="PO-778")\nassert Invoice.from_row(inv.to_row()).po_number == "PO-778"\nassert Invoice("INV-2", "C-1", "EUR", d.date(2024, 3, 1)).po_number is None\nadd_line(inv, "x", 1, "10.00")\nassert export.invoice_row(inv, "DE")["po_number"] == "PO-778"', env=None))


if __name__ == "__main__":
    main(check)
